/// Validates any GTIN (8, 12, 13, 14) via the mod-10 check digit.
bool isValidGtin(String gtin) {
  if (!RegExp(r'^\d{8}$|^\d{12}$|^\d{13}$|^\d{14}$').hasMatch(gtin)) return false;
  return computeCheckDigit(gtin.substring(0, gtin.length - 1)) ==
      int.parse(gtin[gtin.length - 1]);
}

/// Returns the mod-10 check digit for a GTIN body (all digits except the last).
int computeCheckDigit(String body) {
  // From RIGHT, alternately multiply by 3 and 1.
  int sum = 0;
  for (int i = 0; i < body.length; i++) {
    final digit = int.parse(body[body.length - 1 - i]);
    sum += (i.isEven ? 3 : 1) * digit;
  }
  return (10 - sum % 10) % 10;
}

/// Normalizes any GTIN variant to 14 digits (leading-zero padding).
String normalizeToGtin14(String gtin) {
  return gtin.padLeft(14, '0');
}

// Round-trip examples
assert(isValidGtin('01234565'));         // GTIN-8
assert(isValidGtin('8901234567895'));    // EAN-13 (Indian GCP prefix 890)
assert(normalizeToGtin14('8901234567895') == '08901234567895');

// ALWAYS store as GTIN-14 in the DB. Every join / lookup uses the padded form.
class Product {
  final String gtin14;    // padded to 14 digits, indexed
  final String name;
  final String? gcp;
  Product({required this.gtin14, required this.name, this.gcp});
}

// Drift table:
class Products extends Table {
  TextColumn get gtin14 => text().withLength(min: 14, max: 14).unique()();
  TextColumn get name => text()();
}

// Scan flow:
void onScanResult(String rawValue) {
  if (!isValidGtin(rawValue)) {
    showToast('Invalid barcode');
    return;
  }
  final gtin14 = normalizeToGtin14(rawValue);
  final product = await db.productByGtin(gtin14);
  if (product == null) {
    showToast('Unknown SKU');
    return;
  }
  navigateTo(ProductScreen(product));
}
